```python
def update(
    self, resource_id: str, vulnerability_id: str, payload: object
) -> Vulnerability:
    """Validate and replace the mutable fields of a single alert in place.

    The alert is identified by ``vulnerability_id`` scoped to
    ``resource_id``; an id that is unknown, belongs to another resource,
    or was already removed raises :class:`VulnerabilityError` with code
    ``vulnerability_not_found`` and leaves every stored alert untouched.
    ``advisory`` and ``component`` are the alert's identity: the payload
    must repeat them verbatim, otherwise
    :class:`VulnerabilityValidationError` is raised and nothing changes.
    On success only ``severity``, ``summary`` and ``fixed_version`` are
    replaced; the alert keeps its id and its position in the resource's
    submission order and in the global sequence.
    """

    advisory, component, severity, summary, fixed_version = (
        build_vulnerability_fields(payload)
    )
    records = self._records.get(resource_id)
    if records is None:
        raise VulnerabilityError(
            "vulnerability_not_found",
            "No vulnerability alert exists with the requested id.",
        )
    index = next(
        (
            position
            for position, record in enumerate(records)
            if record.id == vulnerability_id
        ),
        None,
    )
    if index is None:
        raise VulnerabilityError(...)

    record = records[index]
    if record.advisory != advisory or record.component != component:
        raise VulnerabilityValidationError(
            "Advisory and component identify the alert and must match "
            "the existing record."
        )

    updated = Vulnerability(
        id=record.id,
        advisory=record.advisory,
        component=record.component,
        severity=severity,
        summary=summary,
        fixed_version=fixed_version,
    )
    records[index] = updated
    self._sequence = [
        (owner_id, updated if alert is record else alert)
        for owner_id, alert in self._sequence
    ]
    return updated
```

